INSERT OR IGNORE INTO vehicle_weapons
  (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire,
   payload, bonus, note)
VALUES
('classic-glitter-boy-qgb-100', 1, 'RG-15 Rapid Acceleration Electromagnetic Rail Gun ("Boom Gun")', 'One round of 200 slugs does 3D6x10 M.D. at Mach 5 - which the book notes is "mistakenly catalogued by most to be Mach 2".', 1, '11,000 feet, about two miles (3.2 km)', 'Equal to the combined hand to hand attacks of the pilot, usually six to eight. Bursts and sprays are not possible.', '100 rounds. A hand reload of about 40 rounds takes roughly fifteen minutes; an optional 400-round carrying drum has 30 M.D.C.', NULL, 'PRINTED "RG-IS" ON THIS PAGE. Stored as RG-15 because the Tarantula''s optional replacement Boom Gun on printed 97 is printed RG-15 and points back here for its stats - the same weapon, and a capital I for a 1 is this corpus''s commonest slip. THE SONIC BOOM: the pilot is insulated, but everyone within 200 feet - triple that underwater - is temporarily deafened. Unprotected, 2D4 minutes of deafness at -8 on initiative and -3 to parry and dodge; in armor, 1D4 minutes with the same penalties. Each shot adds to the duration. It shatters S.D.C. windows and shakes buildings within a 300 foot diameter. QUICK RELOAD: a Reload Team''s automated device refills all 100 rounds in about 45 seconds - three melee rounds - against six minutes by hand for a team, or ten to fifteen for a pilot alone.'),
('classic-glitter-boy-qgb-100', 2, 'Rimouski Weapon Package (left arm)', 'RM-100 Laser Blaster 2D6 M.D. per blast. Laser Finger, three settings: 2D6 S.D.C., 1 M.D. or 1D4 M.D. per blast. RM-100 Vibro-Sword 2D6+3 M.D. per strike.', 1, 'Laser blaster 1000 feet (305 m); laser finger 20 feet (6 m); vibro-sword a 3 foot blade', 'Equal to the combined hand to hand attacks of the pilot', 'Effectively unlimited on both energy weapons - the suit is nuclear', '+1 to strike with the laser blaster and with the laser finger', 'A Quebec-designed retrofit, standard on new builds, bundling three sub-systems into the left forearm. It exists because the Classic is weak in close combat, which matters most to recon, rescue and special-ops suits working without infantry support.'),
('classic-glitter-boy-qgb-100', 3, 'Hand to Hand Combat', 'Restrained punch 1D6 M.D.; full strength punch 2D6 M.D.; tear or pry 1D6 M.D.; kick 2D4 M.D.; running leap kick 4D6 M.D.; body block or ram 2D4 M.D.', 1, 'Reach', 'Elite Glitter Boy Combat Training gives two attacks per round at level one on top of the pilot''s own, and one more at levels 3, 7 and 11', NULL, '+2 on initiative, +2 to strike with rail guns, +2 to strike in hand to hand, +2 to parry, +2 to dodge, +4 to pull punch, +4 to roll with impact', 'The Elite Glitter Boy Combat Training every variant in this file refers back to.'),
('classic-glitter-boy-qgb-100', 4, 'Standard Glitter Boy Sensors and Features', NULL, 0, 'Infrared searchlights and the full optical suite', NULL, NULL, '+2 to strike with the Boom Gun from the advanced laser targeting system', 'Not a weapon. Full optical systems, advanced laser targeting, a distress homing beacon with a 30% chance of being detected by the enemy - sometimes disabled on recon and espionage suits - a self-destruct mechanism, and the laser-resistant chrome armor that halves laser damage across the whole line.'),
('triax-glitter-boy-qgb-5-50', 1, 'TX-550 Boom Gun / Rail Gun', 'One round of 200 slugs does 3D6x10 M.D. at Mach 4', 1, '11,000 feet, about two miles (3.2 km)', 'Equal to the combined hand to hand attacks of the pilot', '100 rounds. A hand reload takes about fifteen minutes, or a field mechanic can swap the empty ammo drum for a fresh one in one to three minutes.', NULL, 'Computer-tracked and voice-commanded, but it traverses only a 60 degree VERTICAL arc and cannot pivot side to side - the pilot turns the whole suit. Sonic boom rules are the Classic Glitter Boy''s.'),
('triax-glitter-boy-qgb-5-50', 2, 'TX-550 Anti-Personnel Laser (above the left shoulder)', '3D6 M.D. per blast', 1, '1000 feet (305 m)', 'Equal to the combined hand to hand attacks of the pilot', 'Effectively unlimited', NULL, 'Rotates through 45 degrees.'),
('triax-glitter-boy-qgb-5-50', 3, 'TX-550 Mini-Missile Launchers (4, near the knees, three each)', 'Armor piercing 1D4x10 M.D. or plasma 1D6x10 M.D. as standard; fragmentation 5D6 M.D. optional for anti-personnel work.', 1, 'About one mile (1.6 km)', 'One at a time, or volleys of two to four', '12 total', NULL, NULL),
('triax-glitter-boy-qgb-5-50', 4, 'Vibro-Sword (right arm, retractable)', '3D6 M.D. per slash', 1, 'Reach', 'Equal to the combined hand to hand attacks of the pilot', NULL, NULL, NULL),
('triax-glitter-boy-qgb-5-50', 5, 'Optional hand-held weapon', NULL, 1, NULL, NULL, NULL, NULL, 'The TX-500 is standard issue; the SK-50 Kicker, the Coalition C-40R and the NG-202 are common substitutes. Heavier weapons such as the Taurus Box Rocket Launchers cut speed and manoeuvrability by 25%.'),
('triax-glitter-boy-qgb-5-50', 6, 'Hand to Hand Combat', NULL, 1, 'Reach', NULL, NULL, NULL, 'As per Elite Glitter Boy Combat Training, printed under the Classic Glitter Boy.'),
('triax-glitter-boy-qgb-5-50', 7, 'Sensors and Features of Note', NULL, 0, NULL, NULL, NULL, NULL, 'Not a weapon. Standard power armor and Glitter Boy features, the latter printed under the Classic Glitter Boy.'),
('glitter-girl-qgb-2-20', 1, 'QST-104 "Double-Up" Assault Cannon', 'Explosive rounds 2D6 M.D. Plasma bolts 6D6+12 M.D.', 1, 'Explosive rounds 6,000 feet (1828 m); plasma bolts 2400 feet (731.5 m)', 'Equal to the combined hand to hand attacks of the pilot, usually five to seven. No bursts or sprays.', 'Explosive: 100 rounds, with 1D4+3 spare clips typically carried; a reload counts as two melee actions. Plasma: 120 blasts at full storage, regenerating two a minute. The detached storage pack alone holds ten blasts, plus four from an E-clip, eight from a long clip or fourteen from an E-clip canister.', '+1 to strike when locked to the Glitter Girl''s own optics', 'It can be fixed in place and voice-commanded to fire and track on its own within 1000 feet - six attacks a round on explosive rounds, three on plasma - but gets NO strike, parry or dodge bonuses while unmanned. A Gigi is authorised to carry two cannons under some conditions, one shoulder-mounted and one hand-held.'),
('glitter-girl-qgb-2-20', 2, 'Shoulder-Mounted Mini-Missile Canister Launchers (2)', 'Armor piercing 1D4x10 M.D. or plasma 1D6x10 M.D.; fragmentation 5D6 M.D. optional.', 1, 'About one mile (1.6 km)', 'One at a time, or a volley of two', 'Two total, one each', NULL, NULL),
('glitter-girl-qgb-2-20', 3, 'Optional Mini-Missile Backpack Unit', 'Armor piercing 1D4x10 M.D. or plasma 1D6x10 M.D.; smoke is noted as useful for marking targets.', 1, 'About one mile (1.6 km)', 'One at a time, or volleys of two or four', '12 total', NULL, NULL),
('glitter-girl-qgb-2-20', 4, 'Optional: RG-14 Rapid Acceleration Electromagnetic Rail Gun ("Boom Gun")', 'As the Classic Glitter Boy''s Boom Gun', 1, 'As the Classic Glitter Boy''s Boom Gun', 'As the Classic Glitter Boy''s Boom Gun', 'As the Classic Glitter Boy''s Boom Gun', NULL, 'Replaces the shoulder QST-104, and the hand-held QST-104 then becomes a second rifle. Available only on special assignment and to squad leaders. NOTE THE DESIGNATION: this is RG-14, where the Classic''s is RG-15.'),
('glitter-girl-qgb-2-20', 5, 'Hand to Hand Combat and Special Bonuses', NULL, 1, 'Reach', NULL, NULL, '+2 on initiative, +3 to strike with the QST-104 or the usual +2 with a Boom Gun, +1 to dodge, +2 to pull punch, on top of Elite Glitter Boy Combat Training', NULL),
('glitter-girl-qgb-2-20', 6, 'Sensor Systems of Note', NULL, 0, NULL, NULL, NULL, NULL, 'Not a weapon. Standard power armor and Glitter Boy features, a distress homing beacon with a 30% chance of enemy detection, and a self-destruct mechanism.'),
('glitter-boy-side-kick-qpa-98', 1, 'QST-98 "Kicker" Grenade Launcher', '5D6 M.D. per round to a 6 foot radius; a burst of three does 2D4x10 M.D. as an unmodified roll with no strike bonus, counting as one melee action.', 1, '1800 feet (548.6 m)', 'Equal to the combined hand to hand attacks of the pilot', '40 without the drum, 120 with the 80-round drum. Swapping the drum takes three melee actions; hand-loading 40 rounds takes four melee rounds, about a minute.', NULL, 'Standard issue, and HAND-HELD: the book states "No weapons are integrated into the power armor of the Side Kick", though its M.D.C. table lists the launcher anyway.'),
('glitter-boy-side-kick-qpa-98', 2, 'Standard Additional Weapons', 'Coalition C-18 Laser Pistol 2D4 M.D.; CS Vibro-Knife 1D6 M.D.; CS hand grenades, fragmentation or plasma.', 1, 'C-18 laser pistol 800 feet (244 m)', NULL, 'C-18: 10 shots, with two to four spare E-clips. Grenades: 1D4, plus 1D4 smoke.', NULL, NULL),
('glitter-boy-side-kick-qpa-98', 3, 'Optional Weapons', NULL, 1, NULL, NULL, NULL, NULL, 'The Coalition C-27 Plasma Cannon, C-12 laser assault rifle and C-14 Fire Breather serve as alternates or backups to the QST-98.'),
('glitter-boy-side-kick-qpa-98', 4, 'Sensors and Features', NULL, 0, 'The searchlight reaches 1000 feet (305 m)', NULL, NULL, '+1 to strike, LONG RANGE ONLY. In hand to hand: +1 on initiative, +1 to parry, +2 to dodge, and +6 to dodge while power-jumping.', 'Not a weapon. Standard power armor features plus the Glitter Boy laser-resistant armor that halves laser damage.'),
('tarantula-glitter-boy-qgb-3-30', 1, 'QST-333 "Shaker" Tri-Cannon', 'Laser 4D6 M.D. Plasma 1D6x10+6 M.D. Rail gun: a single round 1D6 M.D., a typical 30-round burst 1D6x10 M.D.', 1, 'Laser 2000 feet (610 m); plasma 2400 feet (731.5 m), which the book calls a North American record for the type; rail gun 6000 feet (1828 m)', 'Equal to the combined hand to hand attacks of the pilot, usually six to eight. No bursts or sprays on the laser or plasma.', 'Rail gun: 300 rounds in the weapon, ten bursts, with a 3000 round ammo drum holding 100. A Reload Team swaps the drum in 45 seconds.', NULL, 'THE PLASMA OVERHEATS: three bolts a melee round is the maximum before a fail-safe shuts it down. Disabling the fail-safe buys 1D4 more rounds before the weapon explodes for 4D6x10 M.D. to the Glitter Boy and 1D6x10 M.D. in a 15 foot radius, destroying the gun. Its size, weight and heat mean only the Tarantula or a similarly large robot can carry it: a full conversion cyborg may try at -5 to strike with severe balance and knockback penalties, ANOTHER GLITTER BOY OR A GIGI IS -2 TO STRIKE AND TAKES 1 M.D. FROM THE BACKLASH, and the Side Kick cannot use it at all.'),
('tarantula-glitter-boy-qgb-3-30', 2, 'Forearm Ion Blaster (left arm)', '4D6 M.D. per blast', 1, '1000 feet (305 m)', 'Equal to the combined hand to hand attacks of the pilot, usually four to six', 'Effectively unlimited', NULL, NULL),
('tarantula-glitter-boy-qgb-3-30', 3, 'Vibro-Sword (typically the right arm)', '2D6+3 M.D. per strike', 1, 'A 3 foot blade', 'Equal to the combined hand to hand attacks of the pilot', NULL, NULL, NULL),
('tarantula-glitter-boy-qgb-3-30', 4, 'Optional: Type Two Head with Dual Lasers', '2D6 M.D. from a single blast, or 4D6 M.D. from both', 1, '1200 feet (366 m)', 'Equal to the combined hand to hand attacks of the pilot', 'Effectively unlimited', '+1 to strike', 'The Type Two head also carries 310 M.D.C. rather than 290.'),
('tarantula-glitter-boy-qgb-3-30', 5, 'Optional: Forearm Mini-Missile Launcher', 'Armor piercing 1D4x10 M.D. or plasma 1D6x10 M.D.; fragmentation 5D6 M.D. optional.', 1, 'About one mile (1.6 km)', 'Volleys of two to four', 'Two total', NULL, 'Alternates with the ion blaster on the forearm.'),
('tarantula-glitter-boy-qgb-3-30', 6, 'Optional: RG-15 Rapid Acceleration Electromagnetic Rail Gun ("Boom Gun")', 'As the Classic Glitter Boy''s Boom Gun', 1, 'As the Classic Glitter Boy''s Boom Gun', 'As the Classic Glitter Boy''s Boom Gun', 'As the Classic Glitter Boy''s Boom Gun', NULL, 'The Shaker Tri-Cannon can be substituted with the Boom Gun. THIS ENTRY IS WHY THE CLASSIC''S "RG-IS" IS STORED AS RG-15: it names the weapon in full and refers back to the Classic for its stats.'),
('tarantula-glitter-boy-qgb-3-30', 7, 'Hand to Hand Combat', NULL, 1, 'Reach', NULL, NULL, NULL, 'As per Elite Glitter Boy Combat Training, printed under the Classic Glitter Boy.'),
('tarantula-glitter-boy-qgb-3-30', 8, 'Sensors and Features', NULL, 0, NULL, NULL, NULL, NULL, 'Not a weapon. Standard power armor and Glitter Boy features, a distress homing beacon and a self-destruct mechanism.'),
('taurus-glitter-boy-qgb-7-70', 1, 'High-Powered Mortars (2)', 'Explosive: 1D6x10 M.D. from one with a 20 foot blast radius, or 2D6x10 M.D. from both simultaneously as one melee action. Smoke rounds are carried for cover and target marking.', 1, 'About 2.2 miles (3.5 km), 12,000 feet', 'One at a time, or a volley of two', '12 total, six per gun on the armor. The Reload Team''s hover vehicle carries a minimum of 96 rounds per gun plus a QST-104 Double-Up Cannon as a backup weapon.', '+1 to strike within one mile, +1 more if the target is in the open, and +2 more against a large, stationary or slow target. Against a small or moving Glitter Boy-sized target, or anything beyond a mile, -2; against an obscured or out-of-sight target, -3; against a Glitter Boy-sized or smaller target moving faster than 60 mph, -6.', 'THE RELOAD TEAM LOADS AND FIRES THESE while the Side Kick defends both. This is the weapon that makes the Taurus the one variant which never operates alone.'),
('taurus-glitter-boy-qgb-7-70', 2, 'Optional High-Powered Laser Cannons (2)', '1D4x10 M.D. from one, or 2D4x10 M.D. from both as one melee action', 1, '4000 feet (1220 m)', 'Equal to the combined hand to hand attacks of the pilot', 'Effectively unlimited - they run off an independent backpack nuclear supply with a five year life', NULL, 'The laser fit needs NO Reload Team, which is the trade against the mortars.'),
('taurus-glitter-boy-qgb-7-70', 3, 'Optional Weapons', NULL, 1, NULL, NULL, NULL, NULL, 'It can also carry a Boom Gun, the Glitter Girl''s QST-104 Double-Up Assault Cannon, or the "Wolf''s Bite" assault rifle.'),
('taurus-glitter-boy-qgb-7-70', 4, 'Sensors and Features', NULL, 0, NULL, NULL, NULL, NULL, 'Not a weapon. Standard power armor features plus the Glitter Boy laser-resistant armor that halves laser damage.'),
('silver-wolf-glitter-boy-qgb-8-88', 1, 'QST-188 Particle Beam Assault Cannon', '1D6x10+6 M.D. per blast. No bursts or sprays.', 1, '2000 feet (610 m)', 'Equal to the combined hand to hand attacks of the pilot', 'Effectively unlimited - the cannon has its own five year nuclear supply - but after about ten minutes of heavy use, roughly 200 blasts, there is a 01-66% chance it shuts down for 1D6 minutes to cool. Veterans self-limit to three shots a round, or rest a round a minute.', NULL, 'The book calls it the largest, most powerful and longest ranged particle beam weapon known to exist in North America. UNIQUELY IN THIS LINE the Silver Wolf uses no pylon stabilisation and can fire it kneeling, prone, or still slung on its back by voice command or manual trigger - which is what the whole design is for.'),
('silver-wolf-glitter-boy-qgb-8-88', 2, 'Forearm Shield Mounted Mini-Missile Launchers (2)', 'Armor piercing 1D4x10 M.D. or plasma 1D6x10 M.D.; fragmentation 5D6 M.D. optional.', 1, 'About one mile (1.6 km)', 'One at a time, or a volley of two', '8 total, four per shield', NULL, 'Each launcher is 30 of its shield''s 100 M.D.C.'),
('silver-wolf-glitter-boy-qgb-8-88', 3, 'Anti-Personnel Laser (1, at the wrist end of the shield)', '2D6 M.D. single, or 4D6 M.D. double, the double counting as two melee attacks', 1, '1000 feet (305 m)', 'Equal to the combined hand to hand attacks of the pilot, usually six to eight', 'Effectively unlimited', NULL, NULL),
('silver-wolf-glitter-boy-qgb-8-88', 4, 'Vibro-Swords (2, built into the forearm shields)', '3D6 M.D. per slash', 1, 'Reach', 'Equal to the combined hand to hand attacks of the pilot, usually six to eight', NULL, 'Usable as paired weapons', 'The parry bonus is lost if the shields are lost.'),
('silver-wolf-glitter-boy-qgb-8-88', 5, 'Optional and Additional Weapons', NULL, 1, NULL, NULL, NULL, NULL, 'Large rifles, rail guns, or the Side Kick''s QST-98 Kicker Grenade Launcher can replace the particle beam. IT IS TOO SMALL AND HAS NO PYLONS for the traditional Boom Gun or most large Glitter Boy cannons - with one exception, the Glitter Girl''s QST-104 Double-Up Assault Cannon, and only as a fixed mount rather than hand-held.'),
('silver-wolf-glitter-boy-qgb-8-88', 6, 'Sensor Systems of Note', NULL, 0, 'The searchlight reaches 1000 feet (305 m)', NULL, NULL, '+2 on initiative and +1 to strike with energy weapons, LONG RANGE ONLY. In hand to hand: +3 on initiative, +1 to strike, +2 to parry, +2 to dodge.', 'Not a weapon. Standard power armor and Glitter Boy features, a distress homing beacon, a self-destruct mechanism and a searchlight.');

-- Read the result back rather than trusting the exit code.
SELECT count(*) AS got_vessels FROM vehicles
 WHERE source_book LIKE 'Rifts World Book 22: Free Quebec%';
SELECT count(*) AS got_gb_locations FROM vehicle_locations
 WHERE vehicle_slug LIKE '%glitter%';
SELECT count(*) AS got_gb_weapons FROM vehicle_weapons
 WHERE vehicle_slug LIKE '%glitter%';

